const input = $json.body ?? $json;

const rawOrderNumber = String(
  input.order_number ??
  input.orderNumber ??
  input.order ??
  ''
).trim();

const customerEmail = String(
  input.customer_email ??
  input.customerEmail ??
  input.email ??
  ''
).trim().toLowerCase();

const orderNumber = rawOrderNumber.replace(/^#/, '').trim();

const orderIsValid = /^[A-Za-z0-9][A-Za-z0-9-]*$/.test(orderNumber);
const emailIsValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail);

return [{
  json: {
    order_number: orderNumber,
    customer_email: customerEmail,
    valid_input: Boolean(orderNumber && orderIsValid && emailIsValid),
    shopify_search: `name:${orderNumber} test:true`
  }
}];

return [{
  json: {
    success: false,
    verified: false,
    code: 'MISSING_OR_INVALID_INPUT',
    message: 'Please provide a valid order number and the customer email used at checkout.'
  }
}];

/*
PUBLIC REPOSITORY TEMPLATE

Configure these values privately before running the workflow.
For production, prefer n8n credentials / secret management instead of hard-coding.
*/
return [{
  json: {
    ...$json,
    shop_domain: 'YOUR-STORE.myshopify.com',
    client_id: 'YOUR_SHOPIFY_CLIENT_ID',
    client_secret: 'YOUR_SHOPIFY_CLIENT_SECRET'
  }
}];

const requested = $('Validate and Normalize Input').first().json;
const config = $('Shopify Configuration').first().json;

if (!$json.access_token) {
  throw new Error('Shopify access token was not returned.');
}

const search = requested.shopify_search;

const graphqlQuery = `
  query {
    orders(first: 10, query: "${search}") {
      nodes {
        name
        email
        closed
        cancelledAt
        displayFinancialStatus
        displayFulfillmentStatus
        statusPageUrl

        shippingAddress {
          address1
          address2
          city
          provinceCode
          countryCodeV2
          zip
        }

        lineItems(first: 50) {
          nodes {
            name
            quantity
            sku
          }
        }

        fulfillments(first: 10) {
          status
          displayStatus
          trackingInfo(first: 10) {
            company
            number
            url
          }
        }
      }
    }
  }
`;

return [{
  json: {
    order_number: requested.order_number,
    customer_email: requested.customer_email,
    shop_domain: config.shop_domain,
    access_token: $json.access_token,
    graphql_query: graphqlQuery
  }
}];

const requested = $('Validate and Normalize Input').first().json;
const response = $json;

const genericFailure = {
  success: false,
  verified: false,
  code: 'ORDER_NOT_VERIFIED',
  message: 'We could not verify an order with those details. Check the order number and email and try again.'
};

if (response.error || response.errors) {
  return [{
    json: {
      success: false,
      verified: false,
      code: 'SHOPIFY_LOOKUP_UNAVAILABLE',
      message: 'Order lookup is temporarily unavailable. Please try again later.'
    }
  }];
}

const orders = response.data?.orders?.nodes ?? [];

const normalizeOrderName = (value) =>
  String(value ?? '').trim().replace(/^#/, '').toLowerCase();

const requestedOrder = normalizeOrderName(requested.order_number);

const order = orders.find(
  (candidate) => normalizeOrderName(candidate.name) === requestedOrder
);

if (!order) {
  return [{ json: genericFailure }];
}

const storedEmail = String(order.email ?? '').trim().toLowerCase();
const suppliedEmail = String(requested.customer_email ?? '').trim().toLowerCase();

if (!storedEmail || storedEmail !== suppliedEmail) {
  return [{ json: genericFailure }];
}

const address = order.shippingAddress;
const shippingParts = address
  ? [address.address1,address.address2,address.city,address.provinceCode,address.countryCodeV2,address.zip].filter(Boolean)
  : [];

const items = (order.lineItems?.nodes ?? []).map((item) => ({
  name: item.name,
  quantity: item.quantity,
  sku: item.sku || null
}));

const tracking = (order.fulfillments ?? [])
  .flatMap((fulfillment) =>
    (fulfillment.trackingInfo ?? []).map((info) => ({
      company: info.company || null,
      number: info.number || null,
      url: info.url || null,
      fulfillment_status: fulfillment.displayStatus || fulfillment.status || null
    }))
  )
  .filter((entry) => entry.number || entry.url);

const primaryTracking = tracking[0] ?? null;

const orderStatus = order.cancelledAt ? 'CANCELLED' : order.closed ? 'CLOSED' : 'OPEN';

return [{
  json: {
    success: true,
    verified: true,
    code: 'ORDER_VERIFIED',
    message: `Order ${order.name} was verified successfully.`,
    order_number: order.name,
    order_status: orderStatus,
    payment_status: order.displayFinancialStatus || 'UNKNOWN',
    fulfilment_status: order.displayFulfillmentStatus || 'UNKNOWN',
    shipping_address_summary: shippingParts.length ? shippingParts.join(', ') : 'No shipping address available',
    tracking_number: primaryTracking?.number ?? null,
    tracking_url: primaryTracking?.url ?? null,
    tracking,
    items_ordered: items,
    order_status_url: order.statusPageUrl || null
  }
}];
